clinical=dict(component_rationale=d['agents'][0]['explanation'],key_points=['NCCP00222a maintenance and 00222b second-line are distinct indications; both exclude predominantly squamous NSCLC.','Pemetrexed 500 mg/m² IV over 10 minutes on Day 1 every 21 days until progression or unacceptable toxicity.','Source v5 replaced nadir-based wording with current-count bands; confirm clinical wellness in borderline continuation rows.','Renal clearance <45 mL/min, haemodialysis and severe hepatic impairment are outside the routine pathway.','Grade 2 first neurotoxicity: hold to baseline then 100% pemetrexed; grade ≥3 or any recurrence: discontinue.','Any grade diarrhoea requiring admission triggers the severe pathway; mucositis and other toxicities have different restart percentages.','No fixed cycle cap or automatic immune-specific monitoring belongs to standalone pemetrexed.'],patient_selection=dict(treatment_intent='Disease control in locally advanced/metastatic non-squamous NSCLC: maintenance after platinum without progression, or second-line therapy.',disease_and_biomarker_context=[x['description'] for x in P['indications']],eligibility_orientation=['ECOG 0–2. Confirm histology and selected treatment line.','Assess prior treatment, current benefit, molecular/systemic options and patient priorities.','Exclude hypersensitivity, CrCl <45 and breastfeeding. Pregnancy requires careful specialist necessity and risk assessment under SmPC.'],important_cautions=['Do not use this standalone assessment for pembrolizumab/pemetrexed maintenance without the combination protocol and immune checks.','NCCP severe hepatic category is not numerically defined; do not invent bilirubin or transaminase cutoffs.','NCCP bleeding footnote uses CTC v2.0 NCI1998; other Table3 grading edition is unspecified.']),support_summary=[folate,b12,steroid,'Low emetogenic risk: NCIS V8 reference is ondansetron 8 mg orally on the treatment day and metoclopramide 10 mg orally three times daily as required on subsequent days, with individual suitability and duration confirmed.','At CrCl45–79, NSAIDs/high-dose aspirin should be avoided 2 days before, treatment day and 2 days after. Long-half-life NSAIDs: at least5 days before, day of and at least2 days after; necessary coadministration needs close marrow/GI monitoring. See SmPC4.5.'],baseline=['FBC, renal and liver profile.','Histology, maintenance/second-line eligibility, performance status, previous treatment and dose history.','Vitamin schedule, steroid plan, interacting medicines, pregnancy/fertility and breastfeeding discussion.'],before_each_cycle=['FBC, renal and liver profile before each cycle.','Assess interval infection, mouth/bowel/skin/respiratory/neurological symptoms and functional impact.','Check previous reductions, neurotoxicity recurrence, vitamins, steroid and medicines/NSAID plan.'],ongoing=['Disease monitoring according to Consultant plan; no arbitrary scan schedule or fixed cycle cap.','Reassess kidneys if dehydration, illness, interacting drugs or toxicity develops.','Continue folate for21 days beyond the final pemetrexed and review persistent symptoms.'],administration=[administration,'Source preparation: 100 mL sodium chloride0.9% over10 minutes; incompatible with calcium-containing diluents.'],access=['Appropriate IV access and anaphylaxis facilities are required.','Follow local line policy; no routine ambulatory pump or cisplatin hydration course.'])
