# Normalise accidental joined prose without altering URLs, IDs or source filenames.
def tidy(x,key=''):
 if isinstance(x,dict):return {k:tidy(v,k) for k,v in x.items()}
 if isinstance(x,list):return [tidy(v,key) for v in x]
 if isinstance(x,str) and key not in ['id','protocol_id','code','url','source_url','source_ids','script_id','content_version','suite_release','release']:
  for old,new in [('every21','every 21'),('Day1','Day 1'),('for21','for 21'),('least5','least 5'),('least2','least 2'),('CrCl45','CrCl 45'),('ECOG0','ECOG 0'),('stageIIIB','stage IIIB'),('advancedNSCLC','advanced NSCLC'),('cisplatin100','cisplatin 100'),('chloride0.9','chloride 0.9'),('over10','over 10'),('Table1','Table 1'),('Table3','Table 3'),('grade3','grade 3'),('grade≥3','grade ≥3'),('grade≥2','grade ≥2'),('grade2','grade 2'),('versus4','versus 4'),('CI0.','CI 0.'),('SmPC4.5','SmPC 4.5')]:x=x.replace(old,new)
 return x
